//! 死锁检测 —— AI 原生 OS 中的“资源等待图”。 //! //! 传统操作系统：进程竞争互斥资源，构成资源分配图；图中有环即可能死锁； //! 银行家算法做安全性避免；恢复手段为抢占、回滚、终止进程。 //! //! AI 原生 OS：智能体竞争三类 AI 资源 —— 模型实例（推理流水线）、工具租约 //! (单写者租约)、上下文窗口（KV 缓存配额）。智能体之间若循环等待（A 等模型 //! 实例被 B 持有，B 等工具租约被 A 持有），即构成 AI 原生死锁。 //! //! 检测：有向图 DFS 找环路；恢复：建议抢占最低优先级智能体的资源或将其上下文 //! 溢出到长期记忆（类“终止进程/抢占资源”）。 //! //! 接口（供 `deadlock://*` 通道）： //! * `deadlock wait <智能体> <资源>` —— 智能体请求资源，构图边 //! * `deadlock release <智能体> <资源>` —— 释放资源，移除边 //! * `deadlock detect` —— 检测环路，返回涉及智能体 //! * `deadlock recover <智能体>` —— 恢复建议（抢占/溢出/终止）  use std::collections::{BTreeMap, BTreeSet, VecDeque}; use std::sync::{Mutex, OnceLock};  use crate::ai_os::agent_proc::Pid;  /// 资源标识：模型实例 / 工具 / 上下文窗口。 #[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)] pub enum Resource {     ModelInstance(u64),     Tool(String),     ContextWindow(u64), }  /// 等待边：智能体 → 资源（“我正在等待资源”）。 #[derive(Clone, Debug)] pub struct WaitEdge {     pub agent: Pid,     pub resource: Resource, }  /// 死检测图。 pub struct WaitGraph {     /// agent -> 正在等待的资源集合。     waits: BTreeMap<Pid, BTreeSet<Resource>>,     /// resource -> 持有该资源的智能体（简化：一个资源一次只由一个智能体持有，即单写者租约）。     holders: BTreeMap<Resource, Pid>,     detect_count: u64,     cycle_count: u64, }  impl Default for WaitGraph {     fn default() -> Self {         Self::new()     } }  impl WaitGraph {     pub fn new() -> Self {         Self {             waits: BTreeMap::new(),             holders: BTreeMap::new(),             detect_count: 0,             cycle_count: 0,         }     }      /// 智能体请求资源：若资源被他人持有，则建立等待边。     pub fn request(&mut self, agent: Pid, resource: Resource) -> RequestOutcome {         match self.holders.get(&resource) {             Some(holder) if *holder != agent => {                 self.waits.entry(agent).or_default().insert(resource.clone());                 RequestOutcome::Blocked { holder: *holder }             }             _ => {                 // 获得资源：记录持有者，并移除该智能体对该资源的等待边。                 self.holders.insert(resource.clone(), agent);                 if let Some(set) = self.waits.get_mut(&agent) {                     set.remove(&resource);                 }                 RequestOutcome::Granted             }         }     }      /// 释放资源：移除持有关系，唤醒等待者（简化：仅移除边）。     pub fn release(&mut self, agent: Pid, resource: Resource) {         if self.holders.get(&resource) == Some(&agent) {             self.holders.remove(&resource);         }         if let Some(set) = self.waits.get_mut(&agent) {             set.remove(&resource);         }     }      /// 环路检测：DFS，返回所有发现的环路（每个环路为涉及智能体列表）。     pub fn detect(&mut self) -> Vec<Vec<Pid>> {         self.detect_count += 1;         let mut cycles: Vec<Vec<Pid>> = Vec::new();         let mut global_visited: BTreeSet<Pid> = BTreeSet::new();          for start in self.waits.keys().cloned().collect::<Vec<Pid>>() {             if global_visited.contains(&start) {                 continue;             }             let mut stack: Vec<(Pid, Vec<Pid>)> = vec![(start, vec![start])];             let mut on_path: BTreeSet<Pid> = BTreeSet::new();             on_path.insert(start);             let mut found = false;              while !found && !stack.is_empty() {                 let (agent, path) = stack.pop().unwrap();                 on_path.insert(agent);                 // 该智能体等待的资源 → 资源持有者 → 下一个智能体。                 let nexts: Vec<Pid> = self                     .waits                     .get(&agent)                     .into_iter()                     .flat_map(|set| set.iter())                     .filter_map(|res| self.holders.get(res))                     .filter(|h| **h != agent)                     .copied()                     .collect();                 for nxt in nexts {                     if path.contains(&nxt) {                         // 找到环路：从 nxt 开始的一段。                         let idx = path.iter().position(|p| *p == nxt).unwrap();                         let cycle: Vec<Pid> = path[idx..].to_vec();                         if !cycles.iter().any(|c| same_cycle(c, &cycle)) {                             cycles.push(cycle.clone());                             self.cycle_count += 1;                         }                         found = true;                         break;                     }                     if !on_path.contains(&nxt) {                         let mut new_path = path.clone();                         new_path.push(nxt);                         stack.push((nxt, new_path));                     }                 }                 on_path.remove(&agent);             }             for p in &path_of(start, &self.waits) {                 global_visited.insert(*p);             }         }         cycles     }      /// 恢复建议：对每个环路，建议抢占其中 token 预算/优先级最低的智能体，     /// 或将其上下文溢出到长期记忆。     pub fn recover(&self, cycles: &[Vec<Pid>], agent_priorities: &BTreeMap<Pid, u8>) -> Vec<String> {         let mut suggestions = Vec::new();         for cycle in cycles {             let victim = cycle                 .iter()                 .min_by_key(|a| agent_priorities.get(*a).copied().unwrap_or(127))                 .copied()                 .unwrap_or(cycle[0]);             suggestions.push(format!(                 "环路 {:?}：建议抢占智能体 {} 的资源，或将其上下文溢出到长期记忆，或终止该智能体",                 cycle, victim             ));         }         suggestions     }      pub fn edge_count(&self) -> usize {         self.waits.values().map(|s| s.len()).sum()     }      pub fn holder_count(&self) -> usize {         self.holders.len()     }      pub fn status(&self) -> String {         format!(             "waiters={} edges={} holders={} detects={} cycles_found={}",             self.waits.len(),             self.edge_count(),             self.holder_count(),             self.detect_count,             self.cycle_count         )     } }  fn path_of(start: &Pid, waits: &BTreeMap<Pid, BTreeSet<Resource>>) -> Vec<Pid> {     let mut out = vec![*start];     let mut cur = *start;     let mut seen: BTreeSet<Pid> = BTreeSet::new();     seen.insert(cur);     while let Some(set) = waits.get(&cur) {         let nxt: Option<Pid> = set.iter().filter_map(|res| {             // 资源持有者在图外，此处仅返回等待方自身作为路径近似（避免跨模块依赖）。             let _ = res;             None         });         if let Some(n) = nxt {             if seen.contains(&n) {                 break;             }             seen.insert(n);             out.push(n);             cur = n;         } else {             break;         }     }     out }  fn same_cycle(a: &[Pid], b: &[Pid]) -> bool {     if a.len() != b.len() {         return false;     }     // 环路旋转等价。     let n = a.len();     (0..n).any(|shift| {         (0..n).all(|i| a[(i + shift) % n] == b[i])     }) }  #[derive(Clone, Debug)] pub enum RequestOutcome {     Granted,     Blocked { holder: Pid }, }  static WAIT_GRAPH: OnceLock<Mutex<WaitGraph>> = OnceLock::new();  pub fn wait_graph() -> &'static Mutex<WaitGraph> {     WAIT_GRAPH.get_or_init(|| Mutex::new(WaitGraph::new())) }  pub fn init() {     let _ = wait_graph(); }  /// `sense deadlock://graph`：等待图状态。 pub fn deadlock_sense() -> String {     wait_graph().lock().unwrap().status() }  /// 聚合状态摘要。 pub fn status() -> String {     deadlock_sense() }  /// `act deadlock://<op>`：死锁检测与恢复。 pub fn deadlock_act(payload: &str) -> Result<String, String> {     let mut it = payload.split_whitespace();     match it.next().unwrap_or("") {         "wait" => {             let agent: u64 = it.next().ok_or("缺少智能体 id")?.parse().map_err(|e| e.to_string())?;             let res = parse_resource(&mut it)?;             let outcome = wait_graph().lock().unwrap().request(agent, res);             match outcome {                 RequestOutcome::Granted => Ok(format!("智能体 {} 获得资源", agent)),                 RequestOutcome::Blocked { holder } => Ok(format!(                     "智能体 {} 阻塞，等待资源被智能体 {} 持有",                     agent, holder                 )),             }         }         "release" => {             let agent: u64 = it.next().ok_or("缺少智能体 id")?.parse().map_err(|e| e.to_string())?;             let res = parse_resource(&mut it)?;             wait_graph().lock().unwrap().release(agent, res);             Ok(format!("智能体 {} 已释放资源", agent))         }         "detect" => {             let mut g = wait_graph().lock().unwrap();             let cycles = g.detect();             if cycles.is_empty() {                 Ok("未检测到死锁环路".to_string())             } else {                 let mut out = String::new();                 for c in &cycles {                     out.push_str(&format!("死锁环路: {:?}\n", c));                 }                 Ok(out.trim_end().to_string())             }         }         "recover" => {             let _agent: u64 = it.next().ok_or("缺少智能体 id")?.parse().map_err(|e| e.to_string())?;             let g = wait_graph().lock().unwrap();             let cycles = g.detect();             let priorities: BTreeMap<Pid, u8> = BTreeMap::new(); // 简化：均等优先级，由调度域注入             let suggestions = g.recover(&cycles, &priorities);             if suggestions.is_empty() {                 Ok("无死锁，无需恢复".to_string())             } else {                 Ok(suggestions.join(" | "))             }         }         "status" | "" => Ok(deadlock_sense()),         _ => Err(             "用法: deadlock wait <智能体> <模型实例 <id>|工具 <名>|窗口 <id>> | release <智能体> <资源> | detect | recover <智能体> | status"                 .to_string(),         ),     } }  fn parse_resource(it: &mut std::str::SplitWhitespace) -> Result<Resource, String> {     match it.next().unwrap_or("") {         "模型实例" | "model" => {             let id: u64 = it.next().ok_or("缺少模型实例 id")?.parse().map_err(|e| e.to_string())?;             Ok(Resource::ModelInstance(id))         }         "工具" | "tool" => {             let name = it.next().ok_or("缺少工具名")?;             Ok(Resource::Tool(name.to_string()))         }         "窗口" | "window" | "ctx" => {             let id: u64 = it.next().ok_or("缺少窗口 id")?.parse().map_err(|e| e.to_string())?;             Ok(Resource::ContextWindow(id))         }         other => Err(format!("未知资源类型 {}", other)),     } }  #[cfg(test)] mod tests {     use super::*;      #[test]     fn grant_then_block() {         let mut g = WaitGraph::new();         // 智能体 1 持有模型实例 7。         match g.request(1, Resource::ModelInstance(7)) {             RequestOutcome::Granted => {}             _ => panic!("应被授予"),         }         // 智能体 2 请求同一资源 → 阻塞，等待 1。         match g.request(2, Resource::ModelInstance(7)) {             RequestOutcome::Blocked { holder } => assert_eq!(holder, 1),             _ => panic!("应被阻塞"),         }         // 智能体 1 释放后，2 再请求应获得。         g.release(1, Resource::ModelInstance(7));         match g.request(2, Resource::ModelInstance(7)) {             RequestOutcome::Granted => {}             _ => panic!("释放后应获准"),         }     }      #[test]     fn cycle_detection() {         let mut g = WaitGraph::new();         // 构造环路：1 持有工具 A，等待模型 7；2 持有模型 7，等待工具 A。         match g.request(1, Resource::Tool("A".to_string())) {             RequestOutcome::Granted => {}             _ => {}         }         match g.request(2, Resource::ModelInstance(7)) {             RequestOutcome::Granted => {}             _ => {}         }         // 现在 1 等待模型 7（被 2 持有），2 等待工具 A（被 1 持有）。         g.request(1, Resource::ModelInstance(7));         g.request(2, Resource::Tool("A".to_string()));         let cycles = g.detect();         assert!(!cycles.is_empty(), "应检测到环路");         let flat: Vec<Pid> = cycles.iter().flatten().copied().collect();         assert!(flat.contains(&1) && flat.contains(&2));     }      #[test]     fn recover_suggestion() {         let mut g = WaitGraph::new();         let _ = g.request(1, Resource::Tool("A".to_string()));         let _ = g.request(2, Resource::ModelInstance(7));         g.request(1, Resource::ModelInstance(7));         g.request(2, Resource::Tool("A".to_string()));         let cycles = g.detect();         let priorities: BTreeMap<Pid, u8> = BTreeMap::new();         let suggestions = g.recover(&cycles, &priorities);         assert!(!suggestions.is_empty());         assert!(suggestions[0].contains("环路"));     }      #[test]     fn deadlock_act_roundtrip() {         let res = deadlock_act("wait 1 模型实例 7").unwrap();         assert!(res.contains("获得资源"));         let res = deadlock_act("wait 2 模型实例 7").unwrap();         assert!(res.contains("阻塞"));         let res = deadlock_act("detect").unwrap();         assert!(res.contains("未检测到死锁环路"));         let res = deadlock_act("release 1 模型实例 7").unwrap();         assert!(res.contains("已释放"));         let res = deadlock_act("status").unwrap();         assert!(res.contains("waiters="));     } }